import * as React from "react";
import Layout from "../components/layout";
import { graphql, Link, PageProps } from "gatsby";
import  data  from "../data/data.json";
import { UserProfile, HomeContent } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import Palette from "../components/palette";
import ServiceArea from "../components/serviceArea";
import { styles } from "../constants/constants";

const userData: UserProfile = data;

const IndexPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  const homeContent = t("home", { returnObjects: true }) as HomeContent;
  return (
    <Layout data={userData}>
      {/* <Palette /> */}
      <section className={styles.container}>
        <article className={styles.section}>
          <div className="max-w-6xl mx-auto">

          {/* Renderiza Block 1 solo si existe */}
          {homeContent.block1?.map((item: any, index: number) =>
            item.title ? (
              <h2 key={index} className={styles.title}>{item.title}</h2>
            ) : (
              <p key={index} dangerouslySetInnerHTML={{ __html: item.copy }} className={styles.paragraph}/>
            )
          )}

          {/* Renderiza Block 2 solo si existe */}
          {homeContent.block2 && (
            <div className="mt-8">
              {homeContent.block2.some((item) => item.title) && (
                <h3 className={styles.subtitle}>
                  {homeContent.block2.find((item) => item.title)?.title}
                </h3>
              )}

              {homeContent.block2.some((item) => item.copy) && (
                <p
                  className={styles.paragraph}
                  dangerouslySetInnerHTML={{
                    __html: homeContent.block2.find((item) => item.copy)?.copy || "",
                  }}
                />
              )}

              <ul className="grid grid-cols-2 gap-2 mt-4 list-disc pl-8 text-neutral-700 font-bold">
                {homeContent.block2
                  .filter((item) => item.item)
                  .map((item, index) => (
                    <li key={index}>{item.item}</li>
                  ))}
              </ul>
            </div>
          )}
          </div>
        </article>
        <article className={styles.section}>
          <div className={styles.articleWrapper}>
            <div className="bg-[olive] w-full sm:w-1/2 min-h-80"> image placeholder </div>
            <div className="flex flex-col justify-center p-4 items-center w-full sm:w-1/2">
              <h2 className={styles.subtitle}>{t("home.block3.title")}</h2>
              <p className={styles.paragraph}>{t("home.block3.copy")}</p>
              <Link to="/installation-et-reparation" className={styles.button}>{t("home.block3.button")}</Link>
              <div className="flex justify-center mt-4">
              <ServiceArea />
            </div>
            </div>
          </div>
        </article>
        <article className={styles.section}>
          <div className={styles.articleWrapper}>
            <div className="flex flex-col justify-center p-4 items-center w-full sm:w-1/2">
              <h2 className={styles.subtitle}>{t("home.block4.title")}</h2>
              <p className={styles.paragraph}>{t("home.block4.copy")}</p>
              <Link to="/teinture-et-vernissage" className={styles.button}>{t("home.block4.button")}</Link>
              <div className="flex justify-center mt-4">
              <ServiceArea />
            </div>
            </div>
            <div className="bg-[pink] w-full sm:w-1/2 min-h-80"> image placeholder </div>
          </div>
        </article>
        <article className={styles.section}>
          <div className={styles.articleWrapper}>
            <div className="bg-[yellow] w-full sm:w-1/2 min-h-80"> image placeholder </div>
            <div className="flex flex-col justify-center p-4 items-center w-full sm:w-1/2">
              <h2 className={styles.subtitle}>{t("home.block5.title")}</h2>
              <p className={styles.paragraph}>{t("home.block5.copy")}</p>
              <Link to="/sablage-de-plancher" className={styles.button}>{t("home.block5.button")}</Link>
              <div className="flex justify-center mt-4">
              <ServiceArea />
            </div>
            </div>
          </div>
        </article>
        <article className={styles.section}>
  
            <div className="flex flex-col p-4 items-center mx-auto max-w-6xl">
              <h2 className={styles.subtitle}>{t("home.block6.title")}</h2>
              <p className={styles.paragraph}>{t("home.block6.copy")}</p>
            </div>

        </article>
      </section>

    </Layout>
  )
}

export default IndexPage

export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;